import java.util.*;

public class Main {
    int reverseBits(int n) {
        String binaryString = String.format("%32s", Integer.toBinaryString(n)).replace(' ', '0'); // pad to 32 characters
        String reversedString = new StringBuilder(binaryString).reverse().toString();
        return (int) Long.parseLong(reversedString, 2);                // parse the reversed string back into an integer
    }

    public static void main(String[] args) {
        int n = 3;
        Main solution = new Main();
        System.out.println(solution.reverseBits(n));
    }
}

