#include <bits/stdc++.h>
using namespace std;

uint32_t reverseBits(uint32_t n) {
    string binaryString;
    for (int i = 31; i >= 0; i--) binaryString += ((n >> i) & 1) ? '1' : '0';  // build the 32 character binary string
    reverse(binaryString.begin(), binaryString.end());
    uint32_t result = 0;
    for (char ch : binaryString) result = (result << 1) | (ch - '0');           // parse the reversed string back
    return result;
}

int main() {
    uint32_t n = 3;
    cout << reverseBits(n) << endl;
    return 0;
}

