import java.util.*;

public class Main {
    static int[] byteReverseTable = new int[256];                  // precomputed once, outside any single call
    static {
        for (int b = 0; b < 256; b++) {
            int reversedByte = 0, value = b;
            for (int i = 0; i < 8; i++) {
                reversedByte = (reversedByte << 1) | (value & 1);
                value >>= 1;
            }
            byteReverseTable[b] = reversedByte;
        }
    }

    public int reverseBits(int n) {
        int byte0 = n & 0xFF;
        int byte1 = (n >>> 8) & 0xFF;
        int byte2 = (n >>> 16) & 0xFF;
        int byte3 = (n >>> 24) & 0xFF;
        return (byteReverseTable[byte0] << 24) | (byteReverseTable[byte1] << 16) |
               (byteReverseTable[byte2] << 8) | byteReverseTable[byte3];               // reassembled in reverse byte order
    }

    public static void main(String[] args) {
        int n = 3;
        Main solution = new Main();
        System.out.println(solution.reverseBits(n));
    }
}

