#include <bits/stdc++.h>
using namespace std;

vector<int> buildByteReverseTable() {                            // precomputed once, outside any single call
    vector<int> table(256);
    for (int b = 0; b < 256; b++) {
        int reversedByte = 0, value = b;
        for (int i = 0; i < 8; i++) {
            reversedByte = (reversedByte << 1) | (value & 1);
            value >>= 1;
        }
        table[b] = reversedByte;
    }
    return table;
}

vector<int> byteReverseTable = buildByteReverseTable();

uint32_t reverseBits(uint32_t n) {
    uint32_t byte0 = n & 0xFF;
    uint32_t byte1 = (n >> 8) & 0xFF;
    uint32_t byte2 = (n >> 16) & 0xFF;
    uint32_t byte3 = (n >> 24) & 0xFF;
    return (byteReverseTable[byte0] << 24) | (byteReverseTable[byte1] << 16) |
           (byteReverseTable[byte2] << 8) | byteReverseTable[byte3];                 // reassembled in reverse byte order
}

int main() {
    uint32_t n = 3;
    cout << reverseBits(n) << endl;
